command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: MAUNZENDER BEFEHL (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Maunzender Befehl";
    const ahne = "brona"; 
    const finalEffektName = `${gabenName} (Brona)`;
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    // --- 3. TARGET ERMITTELN ---
    let targets = Array.from(game.user.targets);
    if (targets.length === 0 || targets.length > 1) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle genau EIN Ziel (Target) für den Befehl!");
    }
    const targetActor = targets[0].actor;
    if (!targetActor) return;

    let whisperIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(targetActor).forEach(id => whisperIds.add(id));
    getOwners(casterActor).forEach(id => whisperIds.add(id));

    // --- 3.5 ZIEL-PRÜFUNG (MENSCH) ---
    // 🚩 LUNAS FIX: Prüfen, ob das Ziel ein Mensch oder Zweibeiner ist
    const zielSpezies = (targetActor.system?.details?.species?.value || targetActor.system?.details?.species || targetActor.system?.species?.value || "").toLowerCase();
    const isMensch = zielSpezies.includes("mensch") || zielSpezies.includes("zweibeiner");

    if (!isMensch) {
        const failContent = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="margin-bottom: 8px; text-align: center;"><b>${casterActor.name}</b> versucht <b>${targetActor.name}</b> zu befehligen...</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="text-align:center; color:#B30000; font-weight:bold; font-size: 1.1em;">Fehlschlag!</p>
                    <p style="text-align:center;">Die Gabe wirkt nur bei Menschen.<br><span style="font-size: 0.85em; color: #555;">(Aktuelle Spezies des Ziels: ${zielSpezies || "Unbekannt"})</span></p>
                </div>
            </div>
        `;
        let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
        if (msg) {
            await msg.update({ content: failContent, whisper: Array.from(whisperIds) });
        } else {
            await ChatMessage.create({
                speaker: { alias: "System" },
                whisper: Array.from(whisperIds).filter(id => game.users.get(id)),
                content: failContent
            });
        }
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
        return; // Makro bricht hier ab!
    }

    // --- 4. BERECHNUNGEN ---
    const dauerMinuten = qs;
    const dauerSekunden = dauerMinuten * 60;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    // --- 5. EFFEKT ANWENDEN ---
    let alterEffekt = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        description: `Der Mensch wird gezwungen, eine kommunizierte Handlung auszuführen. Er glaubt, die Katze erwartet dies von ihm. (Keine Selbstgefährdung).`,
        duration: { seconds: dauerSekunden }
    }]);

    // --- 6. FLAG-CLEANUP ---
    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    // --- 7. CHAT-KARTE BAUEN ---
    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px;"><b>${casterActor.name}</b> maunzt <b>${targetActor.name}</b> befehlend an.</p>
                <p style="margin-top:0; text-align: justify;">Der Mensch führt eine Handlung durch, von der er glaubt, dass die Vampirkatze sie von ihm erwartet (z.B. durch Gestik kommuniziert).</p>
                <ul class="dsklist" style="margin-bottom: 8px;">
                    <li><b>Ziel:</b> Menschen</li>
                    <li><b>Reichweite:</b> 8 Schritt</li>
                    <li><b style="color: #B30000;">Grenze:</b> Keine Gefährdung des Ziels oder seiner Liebsten.</li>
                </ul>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                    Wirkungsdauer:<br>${dauerMinuten} Minuten <span ${thinStyle}>(QS ${qs})</span>
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent, whisper: Array.from(whisperIds) });
    } else {
        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(whisperIds).filter(id => game.users.get(id)),
            content: cardContent
        });
    }
})();
